// ============================================
// MOCK IA - Classificação por palavras-chave
// Substitui a OpenAI para testes sem token
// ============================================

const message = ($input.first().json.message || '').toLowerCase().trim();

// Palavras-chave por intenção
const keywords = {
  BUY_TICKET: ['comprar', 'quero comprar', 'passagem', 'reservar', 'quero ir', 'quero viajar', 'compra', 'ticket', 'bilhete', 'quero uma passagem', 'me vende'],
  ASK_SCHEDULES: ['horário', 'horarios', 'hora', 'que horas', 'saída', 'saida', 'quando sai', 'próximo barco', 'proximo barco', 'agenda', 'partida'],
  ASK_PRICES: ['preço', 'preco', 'quanto custa', 'valor', 'tarifa', 'custo', 'quanto é', 'quanto e'],
  HUMAN_HELP: ['humano', 'atendente', 'falar com alguém', 'falar com alguem', 'ajuda humana', 'pessoa real', 'operador', 'suporte']
};

// Classificação
let intent = 'OTHER';
for (const [intentName, words] of Object.entries(keywords)) {
  if (words.some(w => message.includes(w))) {
    intent = intentName;
    break;
  }
}

// Extração básica de entidades
const entities = {};

// Origem e destino - padrões comuns
const deParaMatch = message.match(/(?:de|saindo de|partindo de)\s+([a-záàãéêíóôúç\s]+?)\s+(?:para|pra|até|ate)\s+([a-záàãéêíóôúç\s]+?)(?:\s|$|,|\.|!|\?)/i);
if (deParaMatch) {
  entities.origin = deParaMatch[1].trim();
  entities.destination = deParaMatch[2].trim();
}

// Data - formatos dd/mm ou dd/mm/aaaa
const dateMatch = message.match(/(\d{1,2}\/\d{1,2}(?:\/\d{2,4})?)/); 
if (dateMatch) {
  entities.travel_date = dateMatch[1];
}

// Amanhã, hoje, etc
if (message.includes('amanhã') || message.includes('amanha')) {
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  entities.travel_date = tomorrow.toISOString().split('T')[0];
} else if (message.includes('hoje')) {
  entities.travel_date = new Date().toISOString().split('T')[0];
}

// CPF
const cpfMatch = message.match(/(\d{3}\.?\d{3}\.?\d{3}-?\d{2})/);
if (cpfMatch) {
  entities.passenger_cpf = cpfMatch[1];
}

// Nome (após "meu nome é" ou "nome:")
const nameMatch = message.match(/(?:meu nome (?:é|e)|nome:?)\s+([A-ZÁÀÃÉÊÍÓÔÚÇa-záàãéêíóôúç\s]+?)(?:\s*,|\s*\.|$)/i);
if (nameMatch) {
  entities.passenger_name = nameMatch[1].trim();
}

console.log(`[MOCK IA] Mensagem: "${message}"`);
console.log(`[MOCK IA] Intent: ${intent}`);
console.log(`[MOCK IA] Entidades:`, JSON.stringify(entities));

return [{
  json: {
    intent,
    extracted_entities: entities,
    _mock: true,
    _original_message: message
  }
}];
